uniform float speed : 0.0 .. 3.0 = 0.35;   // swell rise rate (cycles / second)
uniform float wavelength : 0.1 .. 0.5 = 0.25; // vertical wavelength in metres
uniform float width : 0.02 .. 0.30 = 0.10;    // crest softness in metres
uniform float amp : 0.0 .. 0.5 = 0.15;        // surface wobble amplitude
uniform vec3 deep : color = 0.01, 0.06, 0.16;
uniform vec3 foam : color = 0.35, 0.75, 0.95;

state fixed rise;   // swell phase in TURNS
state fixed wob;    // wobble phase in TURNS

void update() {
  rise = fract(rise + fixed(dt * speed));
  wob  = fract(wob  + fixed(dt * speed * 1.7));
}

vec3 shade(Led led) {
  // swell front: a soft band travelling up the helix (led.s is arclength 0..1)
  fixed band = fract(fixed(led.s) - rise);
  fixed crest = fixed(1.0) - clamp(band * fixed(1.0) / fixed(width), fixed(0.0), fixed(1.0));

  // gentle surface wobble so the crest breathes around the column
  fixed h = fixed(led.pos.y) * fixed(3.3333);          // ~ turns over the 0.30 m height
  fixed ripple = sin(h * fixed(6.2832) + wob) * fixed(amp);

  fixed v = clamp(crest + ripple * crest, fixed(0.0), fixed(1.0));

  // depth tint: darker toward the floor, foam tint on the crest
  vec3 col = mix(deep, foam, float(v));
  col = col * (0.55 + 0.45 * float(fixed(led.pos.y) * fixed(3.3333)));
  return col;
}
